import java.util.*;

class Solution {
  public List<String> ipToCIDR(String ip, int n) {
    long start = 0;
    for (String part : ip.split("\\.")) start = start * 256 + Integer.parseInt(part);
    List<String> res = new ArrayList<>();
    while (n > 0) {
      // largest aligned block starting at start that does not overshoot n
      long block = start == 0 ? 1L << 32 : start & -start;
      while (block > n) block >>= 1;
      res.add(toIp(start) + "/" + (32 - Long.numberOfTrailingZeros(block)));
      start += block;
      n -= block;
    }
    return res;
  }

  private String toIp(long x) {
    return (x >> 24 & 255) + "." + (x >> 16 & 255) + "." + (x >> 8 & 255) + "." + (x & 255);
  }
}
